<script setup lang="ts">
import {computed} from 'vue'
import {dayBadges,secondsText,type EmployeeMonth,type EffectiveDay} from '../attendanceMonth'
import {modeLabel} from '../attendancePolicy'
const props=defineProps<{employee:EmployeeMonth;english:boolean}>(),emit=defineEmits<{select:[employee:EmployeeMonth,day:EffectiveDay]}>()
const offset=computed(()=>{const first=props.employee.days[0];return first?(new Date(first.workDate+'T00:00:00Z').getUTCDay()+6)%7:0})
</script>
<template><section><h3>{{employee.name}} <small>{{employee.employeeNo}}</small></h3><p>{{[...new Set(employee.days.map(d=>d.mode))].map(m=>modeLabel(m,english)).join(' / ')}}</p><div class="am-calendar"><strong v-for="(n,index) in (english?['M','T','W','T','F','S','S']:['一','二','三','四','五','六','日'])" :key="index">{{n}}</strong><span v-for="n in offset" :key="'offset'+n"></span><button v-for="day in employee.days" :key="day.workDate" :data-state="day.state" :aria-label="day.workDate+': '+(dayBadges(day,english).join(', ')||(day.state==='not_applicable'?(english?'Hours N/A':'工时不适用'):(english?'Normal, effective source':'正常，来源有效')))" @click="emit('select',employee,day)"><strong>{{Number(day.workDate.slice(8))}}</strong><small v-for="badge in dayBadges(day,english)" :key="badge">{{badge}}</small></button></div><dl class="wf-details wf-section"><dt>{{english?'Work':'工时'}}</dt><dd>{{employee.days.every(d=>d.mode==='contract'||d.mode==='free')?(english?'N/A':'不适用'):secondsText(employee.totals.workSeconds,english)}}</dd><dt>{{english?'Confirmed overtime':'已确定计薪加班'}}</dt><dd>{{secondsText(employee.totals.overtimeSeconds,english)}}</dd><dt>{{english?'Pending overtime':'待确定计薪加班'}}</dt><dd>{{secondsText(employee.totals.pendingOvertimeSeconds,english)}}</dd><dt>{{english?'Approved extra work':'批准额外工作'}}</dt><dd>{{secondsText(employee.totals.extraWorkSeconds,english)}}</dd><dt>{{english?'Paid / unpaid leave':'带薪 / 无薪假'}}</dt><dd>{{secondsText(employee.totals.paidLeaveSeconds,english)}} / {{secondsText(employee.totals.unpaidLeaveSeconds,english)}}</dd><dt>{{english?'Absence':'缺勤'}}</dt><dd>{{secondsText(employee.totals.absenceSeconds,english)}}</dd><dt>{{english?'Pending items':'待处理事项'}}</dt><dd>{{employee.totals.pendingCount}}</dd></dl></section></template>
<style scoped>.am-calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:3px}.am-calendar>strong{text-align:center;font-size:12px}.am-calendar button{min-width:0;min-height:76px;padding:5px 2px;display:flex;flex-direction:column;justify-content:flex-start;gap:3px;overflow-wrap:anywhere}.am-calendar small{font-size:10px;line-height:1.3}.am-calendar [data-state=pending],.am-calendar [data-state=stale]{background:#fff4df}.am-calendar [data-state=future],.am-calendar [data-state=unarranged],.am-calendar [data-state=outside_employment]{background:#f0f3f6}@media(max-width:360px){.am-calendar button{min-height:66px}}</style>
